/* ET45 live cloud layer ─────────────────────────────────────────────────────
 *
 * Drapes today's real clouds over the globe: a thin shell just above the
 * surface, lit by the same sun as the earth below it, so the deck is white in
 * daylight, gold along the terminator and dark over the night side.
 *
 * One line to use it, anywhere after the earth exists:
 *
 *     ET45Clouds.attach({ THREE, scene: space, sunDir, camAlt });
 *
 * Nothing else. It adds its own mesh, fetches its own imagery, keeps its own
 * uniforms up to date from mesh.onBeforeRender, refreshes itself when the
 * source publishes a new map, and never throws into the caller: every failure
 * path ends at the bundled texture, so the globe is never bald.
 *
 * Source: clouds.matteason.co.uk, an equirectangular cloud map rebuilt every
 * three hours from EUMETSAT geostationary data. Free, no key, CORS enabled,
 * CC0. Attribution required: "Contains modified EUMETSAT data".
 *
 * Order of preference, each falling through to the next on any failure:
 *   1. the live map for the current 3-hour slot
 *   2. the last live map this browser saw (IndexedDB, survives restarts)
 *   3. NASA GIBS daily true-colour, clouds pulled out of it on the CPU
 *   4. the bundled procedural texture
 */
(function (root) {
  'use strict';

  var DEFAULTS = {
    // ── source ──────────────────────────────────────────────────────────
    // 2048x1024 is ~19km per pixel at the equator, which is finer than the
    // globe is ever asked to show: the layer has faded out long before the
    // descent gets close enough to resolve it. 4096x2048 is available and
    // costs about four times the download for no visible gain.
    size: '2048x1024',
    liveUrl: function (size, slot) {
      return 'https://clouds.matteason.co.uk/images/' + size +
             '/clouds-alpha.png?slot=' + slot;
    },
    credit: 'Clouds: contains modified EUMETSAT data via clouds.matteason.co.uk',
    fallbackCredit: 'Clouds: bundled offline texture (not live weather)',
    fallbackUrl: 'data:image/png;base64,',
    // NASA GIBS, used only if the primary source is unreachable. Daily rather
    // than 3-hourly and it needs clouds separating from land on the CPU, so it
    // is a safety net, not a first choice.
    gibs: true,
    gibsLayer: 'VIIRS_NOAA20_CorrectedReflectance_TrueColor',
    refreshMinutes: 20,      // how often to look for a new 3-hour slot
    slotHours: 3,            // how often the source publishes
    cache: true,             // remember the last good map in IndexedDB

    // ── look ────────────────────────────────────────────────────────────
    radius: 1.0015,          // ~9.5km up, where cloud tops actually are
    opacity: 1.0,
    softLow: 0.050,          // coverage below this is clear sky
    softHigh: 0.920,          // coverage above this is solid deck
    density: 0.94,           // ceiling on opacity: even overcast lets a little through
    limb: 1.55,              // how much thicker the deck reads edge-on
    shade: 0.55,             // self-shading across the cloud tops
    nightAlpha: 0.82,        // overcast still dims the city lights below it
    driftDegPerHour: 1.2,    // gentle eastward advection between refreshes
    // Tied to the prototype's DETAIL_LEVELS[0], which fades its sharp satellite
    // mosaic in between 0.047 and 0.012. The cloud map is ~19km per pixel, so
    // it must leave as that sharp imagery arrives, or the last part of the
    // descent is flown through a grey sheet.
    fadeLowAlt: 0.0120,      // ~76km: layer gone, sharp ground has taken over
    fadeHighAlt: 0.0470,     // ~300km: layer at full strength
    crossfadeMs: 1400,       // swapping in a new map should not be a cut
    renderOrder: -1,         // under the atmosphere, so the limb haze covers it
  };

  /* ── tiny IndexedDB blob store ─────────────────────────────────────────
     Wrapped to the point of paranoia: on a file:// page Chrome hands out an
     opaque origin and every one of these calls can throw or hang, which must
     never be allowed to stop the layer from appearing. */
  var DB = 'et45-clouds', STORE = 'maps';

  function idb() {
    return new Promise(function (res, rej) {
      try {
        var r = indexedDB.open(DB, 1);
        r.onupgradeneeded = function () {
          try { r.result.createObjectStore(STORE); } catch (e) {}
        };
        r.onsuccess = function () { res(r.result); };
        r.onerror = function () { rej(r.error); };
        r.onblocked = function () { rej(new Error('blocked')); };
      } catch (e) { rej(e); }
    });
  }

  function idbGet(key) {
    return idb().then(function (db) {
      return new Promise(function (res, rej) {
        var q = db.transaction(STORE, 'readonly').objectStore(STORE).get(key);
        q.onsuccess = function () { res(q.result); };
        q.onerror = function () { rej(q.error); };
      });
    });
  }

  function idbPut(key, val) {
    return idb().then(function (db) {
      return new Promise(function (res, rej) {
        var t = db.transaction(STORE, 'readwrite');
        t.objectStore(STORE).put(val, key);
        t.oncomplete = function () { res(); };
        t.onerror = function () { rej(t.error); };
      });
    });
  }

  var withTimeout = function (p, ms) {
    return Promise.race([p, new Promise(function (_, rej) {
      setTimeout(function () { rej(new Error('timeout')); }, ms);
    })]);
  };

  /* ── image loading ─────────────────────────────────────────────────────
     An <img> rather than fetch(): a file:// page has an opaque origin, where
     fetch() to a remote host is refused outright but an image with
     crossOrigin='anonymous' still loads against Access-Control-Allow-Origin:*.
     That is the whole reason this app can be opened by double-clicking. */
  function loadImage(url, cors) {
    return new Promise(function (res, rej) {
      var img = new Image();
      if (cors) img.crossOrigin = 'anonymous';
      img.onload = function () { res(img); };
      img.onerror = function () { rej(new Error('load failed: ' + url)); };
      img.src = url;
    });
  }

  function blobToImage(blob) {
    var url = URL.createObjectURL(blob);
    return loadImage(url, false).then(function (img) {
      URL.revokeObjectURL(url); return img;
    }, function (e) { URL.revokeObjectURL(url); throw e; });
  }

  /* Drawing the image once on the CPU buys three things: we learn whether the
     source gave us an alpha channel or a greyscale sheet, we can carve clouds
     out of a true-colour image, and we get a blob to cache. A tainted canvas
     (no CORS headers) throws here; the caller then uses the raw image and
     tells the shader to read luminance instead. */
  function toCoverage(img, mode) {
    var w = img.naturalWidth || img.width, h = img.naturalHeight || img.height;
    var c = document.createElement('canvas');
    c.width = w; c.height = h;
    var ctx = c.getContext('2d', { willReadFrequently: false });
    ctx.drawImage(img, 0, 0);
    var d = ctx.getImageData(0, 0, w, h);   // throws if tainted
    var p = d.data, i, n = p.length;

    if (mode === 'truecolor') {
      // Clouds in a true-colour composite are bright and colourless. Ice and
      // desert are bright too, so lean on the lack of colour rather than
      // brightness alone, and stop trusting either near the poles.
      for (i = 0; i < n; i += 4) {
        var r = p[i], g = p[i + 1], b = p[i + 2];
        var mx = r > g ? (r > b ? r : b) : (g > b ? g : b);
        var mn = r < g ? (r < b ? r : b) : (g < b ? g : b);
        var sat = mx === 0 ? 0 : (mx - mn) / mx;
        var a = (mn / 255 - 0.34) / 0.46;                 // needs real brightness
        a *= 1 - Math.min(1, sat / 0.30);                 // and almost no colour
        var y = Math.floor(i / 4 / w) / h;
        var lat = Math.abs(90 - y * 180);
        if (lat > 60) a *= Math.max(0, 1 - (lat - 60) / 25);  // ice reads as cloud
        p[i] = p[i + 1] = p[i + 2] = 255;
        p[i + 3] = Math.max(0, Math.min(1, a)) * 255;
      }
    } else if (mode === 'luminance') {
      for (i = 0; i < n; i += 4) {
        var l = (p[i] * 0.2126 + p[i + 1] * 0.7152 + p[i + 2] * 0.0722);
        p[i] = p[i + 1] = p[i + 2] = 255;
        p[i + 3] = l;
      }
    } else {
      // Already an alpha map. Force RGB white so a JPEG-ish grey cast in the
      // colour channels cannot tint the deck.
      for (i = 0; i < n; i += 4) { p[i] = p[i + 1] = p[i + 2] = 255; }
    }
    ctx.putImageData(d, 0, 0);
    return c;
  }

  function hasAlpha(img) {
    return /\.png(\?|$)/i.test(img.src) || /^blob:|^data:image\/png/i.test(img.src);
  }

  /* ── shaders ───────────────────────────────────────────────────────────── */

  var VERT = [
    'varying vec2 vUv; varying vec3 vN; varying vec3 vW;',
    'void main(){',
    '  vUv = uv;',
    '  vN = normalize(mat3(modelMatrix) * normal);',
    '  vec4 w = modelMatrix * vec4(position, 1.0);',
    '  vW = w.xyz;',
    '  gl_Position = projectionMatrix * viewMatrix * w;',
    '}'
  ].join('\n');

  var FRAG = [
    'uniform sampler2D mapA, mapB;',
    'uniform float modeA, modeB, blend;',   // 0 = alpha channel, 1 = luminance
    'uniform vec3 sunDir;',
    'uniform float camAlt, drift, opacity, softLow, softHigh, limb;',
    'uniform float nightAlpha, fadeLowAlt, fadeHighAlt, density, shade;',
    'varying vec2 vUv; varying vec3 vN; varying vec3 vW;',

    'float cover(sampler2D m, vec2 uv, float mode){',
    '  vec4 t = texture2D(m, uv);',
    '  return mix(t.a, dot(t.rgb, vec3(0.2126, 0.7152, 0.0722)), mode);',
    '}',
    'float covMix(vec2 uv){',
    '  return mix(cover(mapA, uv, modeA), cover(mapB, uv, modeB), blend);',
    '}',

    'void main(){',
    '  vec2 uv = vec2(vUv.x - drift, vUv.y);',
    '  float raw = covMix(uv);',
    '  float a = raw;',

    // Soft edges: thin cirrus stays a veil, cores go solid, and nothing has a
    // hard cut-out rim against the ocean.
    '  a = smoothstep(softLow, softHigh, a) * density;',

    '  vec3 N = normalize(vN);',
    '  vec3 V = normalize(cameraPosition - vW);',
    '  vec3 S = normalize(sunDir);',
    '  float d = dot(N, S);',

    // Edge-on, the line of sight runs the long way through the deck, so the
    // limb thickens. This is most of what makes the layer read as depth
    // rather than as a decal.
    '  float rim = 1.0 - clamp(dot(N, V), 0.0, 1.0);',
    '  a = clamp(a * mix(1.0, limb, pow(rim, 1.6)), 0.0, 1.0);',

    // Cloud tops are ~10km up, so they catch the sun a few degrees of arc
    // before the ground does and hold it a few degrees longer. The offset
    // terminator is small and it is exactly what sells the altitude.
    '  float day = smoothstep(-0.22, 0.18, d);',

    // Cloud tops are not flat. Take the slope of the coverage field, tilt the
    // normal by it and light that, and the deck gains the piled, shaded relief
    // that tells the eye it has thickness. Without this it is a white decal.
    '  vec3 east = normalize(cross(vec3(0.0, 1.0, 0.0), N));',
    '  vec3 north = cross(N, east);',
    '  float e = 0.0016;',
    '  float gx = covMix(uv + vec2(e, 0.0)) - covMix(uv - vec2(e, 0.0));',
    '  float gy = covMix(uv + vec2(0.0, e)) - covMix(uv - vec2(0.0, e));',
    '  vec3 Nc = normalize(N - (gx * east + gy * north) * shade * 3.4);',
    '  float relief = clamp(dot(Nc, S) * 1.06 + 0.10, 0.0, 1.35);',
    '  float flat_ = clamp(d, 0.0, 1.0);',
    '  float form = mix(1.0, relief / max(flat_, 0.22), clamp(shade, 0.0, 1.0));',
    '  form = clamp(form, 0.55, 1.30);',

    '  vec3 lit = vec3(1.0, 0.995, 0.985) * form;',
    // Sunrise and sunset along the terminator.
    '  float golden = exp(-pow((d - 0.02) / 0.17, 2.0));',
    '  lit = mix(lit, vec3(1.26, 0.86, 0.62), golden * 0.80);',
    // Night: not black, or the deck punches holes in the city lights; just
    // dark enough to read as unlit cloud with a little moonlight on top.
    '  vec3 dark = vec3(0.020, 0.028, 0.050) + vec3(0.030, 0.034, 0.046) * 0.5;',
    '  vec3 col = mix(dark, lit, day);',

    // Overcast genuinely hides the lights underneath it, so keep most of the
    // opacity at night rather than fading the deck out.
    '  a *= mix(nightAlpha, 1.0, day);',

    // On the way down the camera passes through the deck. Fade it out before
    // then: the map is ~19km per pixel and would be a blurry sheet up close.
    '  a *= smoothstep(fadeLowAlt, fadeHighAlt, camAlt);',

    '  a *= opacity;',
    '  if (a < 0.002) discard;',
    '  gl_FragColor = vec4(col, a);',
    '}'
  ].join('\n');

  /* ── the layer ─────────────────────────────────────────────────────────── */

  function attach(opts) {
    opts = opts || {};
    var cfg = {};
    var k;
    for (k in DEFAULTS) if (DEFAULTS.hasOwnProperty(k)) cfg[k] = DEFAULTS[k];
    for (k in opts) if (opts.hasOwnProperty(k)) cfg[k] = opts[k];

    var THREE = opts.THREE || root.THREE;
    if (!THREE) throw new Error('ET45Clouds: three.js not found');

    var sunDir = opts.sunDir || new THREE.Vector3(1, 0, 0);
    // Shares the caller's object by reference where one is given, so the
    // prototype's own sun and altitude keep driving this layer with no glue.
    var camAlt = opts.camAlt || { value: 1.0 };
    var ownAlt = !opts.camAlt;

    var blank = new THREE.DataTexture(new Uint8Array([255, 255, 255, 0]), 1, 1);
    blank.needsUpdate = true;

    var uni = {
      mapA: { value: blank }, mapB: { value: blank },
      modeA: { value: 0 }, modeB: { value: 0 }, blend: { value: 0 },
      sunDir: { value: sunDir }, camAlt: camAlt,
      drift: { value: 0 }, opacity: { value: cfg.opacity },
      softLow: { value: cfg.softLow }, softHigh: { value: cfg.softHigh },
      limb: { value: cfg.limb }, nightAlpha: { value: cfg.nightAlpha },
      density: { value: cfg.density }, shade: { value: cfg.shade },
      fadeLowAlt: { value: cfg.fadeLowAlt }, fadeHighAlt: { value: cfg.fadeHighAlt }
    };

    var mesh = new THREE.Mesh(
      new THREE.SphereGeometry(cfg.radius, 160, 96),
      new THREE.ShaderMaterial({
        uniforms: uni, vertexShader: VERT, fragmentShader: FRAG,
        transparent: true, depthWrite: false, side: THREE.FrontSide
      }));
    mesh.name = 'et45-clouds';
    mesh.renderOrder = cfg.renderOrder;
    mesh.frustumCulled = false;

    var state = {
      source: 'none', slot: -1, at: null, fading: 0, t0: 0,
      credit: cfg.credit, error: null
    };

    var t0 = (root.performance && root.performance.now)
      ? function () { return root.performance.now(); }
      : function () { return Date.now(); };
    var last = t0();

    mesh.onBeforeRender = function (renderer, scene, camera) {
      var now = t0(), dt = Math.min(0.1, (now - last) / 1000);
      last = now;

      // Drift is in texture space, so it wraps for free.
      uni.drift.value = (uni.drift.value + dt * cfg.driftDegPerHour / 3600 / 360) % 1;

      if (ownAlt && camera) camAlt.value = camera.position.length() - cfg.radius;

      if (state.fading) {
        var f = (now - state.t0) / cfg.crossfadeMs;
        if (f >= 1) {
          // Promote B to A and let the old A go, so the next arrival has a
          // clean slot to fade into.
          if (uni.mapA.value && uni.mapA.value !== blank) uni.mapA.value.dispose();
          uni.mapA.value = uni.mapB.value; uni.modeA.value = uni.modeB.value;
          uni.mapB.value = blank; uni.blend.value = 0; state.fading = 0;
        } else {
          uni.blend.value = f * f * (3 - 2 * f);
        }
      }
    };

    if (cfg.scene) cfg.scene.add(mesh);

    /* Install a new map, fading from whatever is showing. */
    function install(source, img, mode, slotValue) {
      var tex = new THREE.Texture(img);
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.minFilter = THREE.LinearMipmapLinearFilter;
      tex.magFilter = THREE.LinearFilter;
      tex.generateMipmaps = true;
      if (THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;
      if (opts.renderer) {
        tex.anisotropy = opts.renderer.capabilities.getMaxAnisotropy();
      }
      tex.needsUpdate = true;
      // Upload now rather than on the frame it first appears, so swapping the
      // map in never costs a hitch mid-flight.
      if (opts.renderer && opts.renderer.initTexture) opts.renderer.initTexture(tex);

      if (uni.mapA.value === blank) {
        uni.mapA.value = tex; uni.modeA.value = mode;
        uni.blend.value = 0; state.fading = 0;
      } else {
        if (uni.mapB.value && uni.mapB.value !== blank) uni.mapB.value.dispose();
        uni.mapB.value = tex; uni.modeB.value = mode;
        state.fading = 1; state.t0 = t0();
      }
      state.source = source;
      state.at = new Date();
      if (slotValue != null) state.slot = slotValue;
    }

    var slotOf = function (d) {
      return Math.floor(d.getTime() / (cfg.slotHours * 3600 * 1000));
    };

    /* Try the live source, normalising on the CPU where we are allowed to. */
    function tryLive(slot) {
      var url = cfg.liveUrl(cfg.size, slot);
      return withTimeout(loadImage(url, true), 30000).then(function (img) {
        var canvas = null;
        try { canvas = toCoverage(img, hasAlpha(img) ? 'alpha' : 'luminance'); }
        catch (e) { canvas = null; }   // tainted: no CORS headers today

        if (!canvas) {
          // Still perfectly usable, we just cannot cache it or clean it up.
          install('live', img, hasAlpha(img) ? 0 : 1, slot);
          return 'live (uncached)';
        }
        state.credit = cfg.credit;
        install('live', canvas, 0, slot);
        if (cfg.cache && canvas.toBlob) {
          try {
            canvas.toBlob(function (b) {
              if (b) idbPut('last', { slot: slot, blob: b, at: Date.now() })
                       .catch(function () {});
            }, 'image/png');
          } catch (e) {}
        }
        return 'live';
      });
    }

    function tryCache() {
      if (!cfg.cache) return Promise.reject(new Error('cache off'));
      return withTimeout(idbGet('last'), 4000).then(function (rec) {
        if (!rec || !rec.blob) throw new Error('empty');
        return blobToImage(rec.blob).then(function (img) {
          state.credit = cfg.credit;
          install('cache', img, 0, rec.slot);
          return 'cache';
        });
      });
    }

    function tryGibs() {
      if (!cfg.gibs) return Promise.reject(new Error('gibs off'));
      // Yesterday: today's composite is not complete until the satellite has
      // flown the whole globe, and a half-built map has black wedges in it.
      var d = new Date(Date.now() - 26 * 3600 * 1000).toISOString().slice(0, 10);
      var url = 'https://gibs.earthdata.nasa.gov/wms/epsg4326/best/wms.cgi' +
        '?SERVICE=WMS&VERSION=1.3.0&REQUEST=GetMap&CRS=EPSG:4326' +
        '&LAYERS=' + encodeURIComponent(cfg.gibsLayer) +
        '&BBOX=-90,-180,90,180&WIDTH=2048&HEIGHT=1024&FORMAT=image/png&TIME=' + d;
      return withTimeout(loadImage(url, true), 30000).then(function (img) {
        var canvas = toCoverage(img, 'truecolor');   // throws if tainted
        install('gibs', canvas, 0, null);
        state.credit = 'Clouds: NASA GIBS / VIIRS';
        return 'gibs';
      });
    }

    function tryFallback() {
      return loadImage(cfg.fallbackUrl, false).then(function (img) {
        state.credit = cfg.fallbackCredit;
        install('fallback', img, 1, null);
        return 'fallback';
      });
    }

    /* Show something immediately, then improve on it. The bundled texture
       loads from disk in a few milliseconds while the live map is still in
       flight, so the globe is never bare and never pops from bare to clouded. */
    function load(force) {
      var slot = slotOf(new Date());
      if (!force && state.slot === slot && state.source === 'live') {
        return Promise.resolve('current');
      }
      return tryLive(slot)
        .catch(function (e) { state.error = e.message; return tryCache(); })
        .catch(function () { return tryGibs(); })
        .catch(function () {
          // Only reach for the bundled texture if nothing is showing yet;
          // a stale real map beats a fake one.
          if (state.source !== 'none') throw new Error('kept ' + state.source);
          return tryFallback();
        })
        .catch(function (e) { return 'kept: ' + e.message; });
    }

    var first = tryFallback().catch(function () {}).then(function () {
      return load(true);
    });

    var timer = setInterval(function () { load(false); },
                            Math.max(1, cfg.refreshMinutes) * 60000);

    return {
      mesh: mesh,
      uniforms: uni,
      config: cfg,
      ready: first,
      status: function () {
        return { source: state.source, at: state.at, slot: state.slot,
                 credit: state.credit, error: state.error,
                 opacity: uni.opacity.value };
      },
      credit: function () { return state.credit; },
      refresh: function () { return load(true); },
      set: function (key, value) {
        cfg[key] = value;
        if (uni[key]) uni[key].value = value;
      },
      dispose: function () {
        clearInterval(timer);
        if (mesh.parent) mesh.parent.remove(mesh);
        mesh.geometry.dispose();
        [uni.mapA.value, uni.mapB.value].forEach(function (t) {
          if (t && t !== blank) t.dispose();
        });
        blank.dispose();
        mesh.material.dispose();
      }
    };
  }

  root.ET45Clouds = { attach: attach, DEFAULTS: DEFAULTS };

  if (typeof module !== 'undefined' && module.exports) module.exports = root.ET45Clouds;
})(typeof window !== 'undefined' ? window : this);
